MATCH (db:DrainageBasin)-[:locatedIn]->(:Country)
WHERE EXISTS { MATCH (r:River {name: "Congo"})-[:partOf]->(db) }
  AND EXISTS { MATCH (l:Lake {name: "Lake Mai-Ndombe"})-[:partOf]->(db) }
RETURN db.name

MATCH (c:Country)-[:locatedIn]->(:Continent)
WHERE EXISTS { MATCH (m:Mountain)-[:locatedIn]->(c) WHERE m.name = "Pik Przhevalsky" }
  AND EXISTS { MATCH (r:River)-[:flowsThrough]->(c) WHERE r.name = "Dashui Qu" }
RETURN c.name, c.area_km2

MATCH (r:River)-[:flowsInto]->(o:Ocean {name: "Atlantic Ocean"})
WHERE EXISTS { MATCH (r)-[:flowsThrough]->(:Country {name: "Togo"}) }
RETURN DISTINCT r.name
